<script>
(function($,window,document){"use strict";if(!window.AppDataTable||!AppDataTable.ensureAvailable())return;var actions=[],timer=null,has=AppDataTable.has,A_CREATE=2,A_UPDATE=3;function esc(v){return String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function money(v){return"₹"+Number(v||0).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}function qty(v){return Number(v||0).toLocaleString("en-IN",{maximumFractionDigits:3})}function ds(v){v=Number(v);return v===3?"Delivered":(v===2?"Partially Delivered":(v===4?"Cancelled":"Pending"))}
var table=AppDataTable.init("#orderTable",{serverSide:true,searching:true,scrollX:true,autoWidth:false,order:[[1,"desc"]],buttons:[{extend:"copyHtml5",text:"Copy",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6,7,8]}},{extend:"csvHtml5",text:"CSV",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6,7,8]}},{extend:"excelHtml5",text:"Excel",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6,7,8]}},{extend:"pdfHtml5",text:"PDF",orientation:"landscape",pageSize:"A4",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6,7,8]}},{extend:"print",text:"Print",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6,7,8]}}],ajax:function(d,cb){var p=new URLSearchParams();p.set("datatable","1");p.set("draw",d.draw);p.set("start",d.start);p.set("length",d.length);p.set("search[value]",d.search.value||"");if(document.getElementById("statusFilter").value)p.set("delivery_status",document.getElementById("statusFilter").value);App.api("api/orders.php?"+p.toString()).then(function(r){actions=(r.data.allowed_actions||[]).map(Number);document.getElementById("addButton").hidden=!has(actions,A_CREATE);AppDataTable.applyExportPermissions(table,actions);cb(r.data.datatable)}).catch(function(e){App.showError(e,"Unable to load Orders.");cb({draw:d.draw,recordsTotal:0,recordsFiltered:0,data:[]})})},columns:[{data:"sale_no",render:function(v,t){return t==="display"?esc(v):v}},{data:"sale_date"},{data:"customer_name",render:function(v,t){return t==="display"?esc(v):v}},{data:"line_name",render:function(v,t){return t==="display"?esc(v):v}},{data:"ordered_qty",className:"dt-body-right",render:function(v,t){return t==="display"?qty(v):Number(v||0)}},{data:"delivered_qty",className:"dt-body-right",render:function(v,t){return t==="display"?qty(v):Number(v||0)}},{data:"pending_qty",className:"dt-body-right",render:function(v,t){return t==="display"?qty(v):Number(v||0)}},{data:"grand_total",className:"dt-body-right",render:function(v,t){return t==="display"?money(v):Number(v||0)}},{data:"delivery_status",render:function(v,t){var x=ds(v);return t==="display"?'<span class="pill '+(Number(v)===3?'active':(Number(v)===4?'danger':'pending'))+'">'+x+'</span>':x}},{data:null,orderable:false,searchable:false,className:"table-action-icons",render:function(d,t,row){if(t!=="display")return"";var editable=Number(row.delivery_status)!==3&&Number(row.delivery_status)!==4&&has(actions,A_UPDATE);return App.iconActionHtml({href:row.edit_url,icon:editable?"pencil":"eye",label:editable?"Edit Order":"View Order"})}}],drawCallback:function(){if(window.lucide)lucide.createIcons()}});var c=document.getElementById("orderTable").closest(".table-card"),s=c?c.querySelector(".app-table-search-row"):null;if(s)s.remove();document.getElementById("masterSearch").addEventListener("input",function(){clearTimeout(timer);timer=setTimeout(function(){table.search(document.getElementById("masterSearch").value.trim()).draw()},350)});document.getElementById("statusFilter").addEventListener("change",function(){table.ajax.reload(null,true)});if(window.lucide)lucide.createIcons();})(jQuery,window,document);
